actions.script:
period = period == 'month' ? 'month' : 'all'
def today = java.time.LocalDate.parse(new java.text.SimpleDateFormat('yyyy-MM-dd').format(ec.user.nowTimestamp))
def start = java.sql.Timestamp.valueOf(today.withDayOfMonth(1).atStartOfDay())
def end = java.sql.Timestamp.valueOf(today.withDayOfMonth(1).plusMonths(1).atStartOfDay())
def within = { date -> period == 'all' || (date && date >= start && date < end) }
sourceId = sourceCatalogue.any { it.leadSourceId == sourceId } ? sourceId : ''
campaignId = campaigns.any { it.campaignId == campaignId } ? campaignId : ''
filteredLeads = allLeads.findAll { within(it.createdDate) && (!sourceId || (it.firstTouchSourceId ?: it.leadSourceId ?: 'Unknown') == sourceId) && (!campaignId || it.campaignId == campaignId) }
def selectedIds = filteredLeads*.leadId as Set
filteredOpps = allOpportunities.findAll { (!sourceId || (it.leadSourceId ?: 'Unknown') == sourceId) && (!campaignId || it.campaignId == campaignId) && (period == 'all' || selectedIds.contains(it.leadId)) }
filteredActivities = allActivities.findAll { within(it.dueDate ?: it.activityDate) }
def sourceNames = sourceCatalogue.collectEntries { [(it.leadSourceId):it.description] }
def sourceKeys = filteredLeads.collect { it.firstTouchSourceId ?: it.leadSourceId ?: 'Unknown' }.unique().sort()
sourceRows = sourceKeys.collect { key ->
    def leads = filteredLeads.findAll { (it.firstTouchSourceId ?: it.leadSourceId ?: 'Unknown') == key }
    def opps = filteredOpps.findAll { (it.leadSourceId ?: 'Unknown') == key }
    def won = opps.findAll { it.opportunityStageId == 'SoClosedWon' && within(it.wonDate) }
    def qualified = leads.count { it.statusId in ['LeadQualified','LeadConverted'] }
    [sourceId:key, sourceName:sourceNames[key] ?: key, leads:leads.size(),
     qualified:qualified, qualifiedPercent:leads ? (qualified * 100 / leads.size()).intValue() : 0,
     opportunities:opps.size(), won:won.size(), wonValue:(won.sum { it.estimatedAmount ?: 0G } ?: 0G)]
}
latestRows = filteredLeads.groupBy { it.latestTouchSourceId ?: it.leadSourceId ?: 'Unknown' }
    .collect { key, rows -> [sourceName:sourceNames[key] ?: key, leads:rows.size()] }
    .sort { it.sourceName }
openOpps = filteredOpps.findAll { !['SoClosedWon','SoClosedLost'].contains(it.opportunityStageId) }
forecastRows = stages.findAll { stage -> openOpps.any { it.opportunityStageId == stage.opportunityStageId } }
    .collect { stage ->
        def rows = openOpps.findAll { it.opportunityStageId == stage.opportunityStageId }
        [stageName:stage.description, deals:rows.size(), amount:(rows.sum { it.estimatedAmount ?: 0G } ?: 0G),
         weighted:(rows.sum { it.expectedRevenue ?: 0G } ?: 0G)]
    }
completedActivities = filteredActivities.count { it.statusId == 'Completed' }
overdueActivities = filteredActivities.count { it.statusId != 'Completed' && it.dueDate && it.dueDate < ec.user.nowTimestamp }
unassignedLeads = filteredLeads.count { !it.assignedToUserId }
def scheduledLeadIds = allActivities.findAll { it.statusId == 'Scheduled' && it.leadId }.collect { it.leadId } as Set
unattendedLeads = filteredLeads.count { it.statusId !in ['LeadLost','LeadConverted'] && !scheduledLeadIds.contains(it.leadId) }
wonCount = filteredOpps.count { it.opportunityStageId == 'SoClosedWon' && within(it.wonDate) }
lostCount = filteredOpps.count { it.opportunityStageId == 'SoClosedLost' && within(it.lostDate) }
winRate = wonCount + lostCount ? (wonCount * 100 / (wonCount + lostCount)).intValue() : 0
lostRows = filteredOpps.findAll { it.opportunityStageId == 'SoClosedLost' && within(it.lostDate) }
    .groupBy { it.lostReason ?: 'Unspecified' }.collect { key, rows ->
        [reason:key, deals:rows.size(), amount:(rows.sum { it.estimatedAmount ?: 0G } ?: 0G)]
    }
